/**
 * Guards for the ids a write points at.
 *
 * A payload can name other rows — an assignee, a project lead, labels, a
 * parent issue, a comment to reply to — and each of those has to be usable
 * from the organization the change is made in. The rule is the same
 * everywhere: a row that belongs to another organization is a tenant
 * violation, and anything else that cannot be used (missing, archived, not a
 * current member, wrong project or issue, not top-level) is "not found".
 *
 * Every guard runs before the write it protects, so a refusal leaves no trace.
 */
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError } from "./_support";
import type { CommentId, IssueId, LabelId, ProjectId, UserId } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { OrgId } from "@/types/common";

/** Members who count as "in the workspace": live rows with an active seat. */
export async function isCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<boolean> {
  const member = await memberRepo.findMember(orgId, userId);
  return member !== null && member.status === "active";
}

/** An assignee or project lead must be a current member of the workspace. */
export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  if (!(await isCurrentMember(orgId, userId))) {
    throw new NotFoundError("Member", userId);
  }
}

/**
 * Every label must be one of the actor's organization's own. Returns the ids
 * with duplicates dropped, in first-appearance order, ready to be attached.
 */
export async function resolveOwnLabelIds(
  actor: Actor,
  labelIds: readonly LabelId[],
): Promise<readonly LabelId[]> {
  const unique = [...new Set(labelIds)];
  const found = new Map(
    (await labelRepo.findLabelsAcrossOrgs(unique)).map((label) => [
      label.id,
      label,
    ]),
  );

  for (const labelId of unique) {
    const label = found.get(labelId);
    if (label === undefined) throw new NotFoundError("Label", labelId);
    assertOrgScope(actor, label.orgId);
  }

  return unique;
}

/** A parent must be a live issue of the same project as the new sub-issue. */
export async function assertUsableParentIssue(
  actor: Actor,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueAcrossOrgs(parentId);
  if (parent === null) throw new NotFoundError("Issue", parentId);

  assertOrgScope(actor, parent.orgId);
  if (parent.archivedAt !== null || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }

  return parent;
}

/** A reply must be to a live, top-level comment on the same issue. */
export async function assertUsableReplyTarget(
  actor: Actor,
  issueId: IssueId,
  parentId: CommentId,
): Promise<Comment> {
  const parent = await commentRepo.findCommentAcrossOrgs(parentId);
  if (parent === null) throw new NotFoundError("Comment", parentId);

  assertOrgScope(actor, parent.orgId);
  if (
    parent.archivedAt !== null ||
    parent.issueId !== issueId ||
    parent.parentId !== null
  ) {
    throw new NotFoundError("Comment", parentId);
  }

  return parent;
}

