cat > tests/services/reference-integrity.test.ts <<'EOF'
/**
 * Everything a change points at must be usable from the organization the
 * change is made in: assignees, project leads, labels, parent issues, reply
 * targets and mentioned people. A refused change changes nothing.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Comment } from "@/types/comment";
import type { LabelId } from "@/types/common";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let home: Tenant;
let other: Tenant;
let homeIssue: Issue;
let otherIssue: Issue;

const newIssue = (title: string, extra: Record<string, unknown> = {}) => ({
  ...issueInput(home.org.id, home.project.id, { title }),
  ...extra,
});

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  home = await createTenant("refhome");
  other = await createTenant("refother");
  homeIssue = await issueService.createIssue(home.actors.member, newIssue("Home issue"));
  otherIssue = await issueService.createIssue(
    other.actors.member,
    issueInput(other.org.id, other.project.id, { title: "Other issue" }),
  );
});

afterAll(() => {
  cleanup();
});

async function countIssues(): Promise<number> {
  return issueRepo.countIssues(home.org.id, home.project.id, { includeArchived: true });
}

describe("labels", () => {
  it("refuses another workspace's label on create and update, and shows it nowhere", async () => {
    const foreign = await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "Globex secret",
      color: "#000000",
      description: null,
    });
    const own = await labelRepo.insertLabel({
      orgId: home.org.id,
      name: "Bug",
      color: "#ff0000",
      description: null,
    });

    const before = await countIssues();
    await expect(
      issueService.createIssue(home.actors.member, newIssue("Labelled", { labelIds: [own.id, foreign.id] })),
    ).rejects.toBeInstanceOf(TenantScopeError);
    expect(await countIssues()).toBe(before);

    await expect(
      issueService.createIssue(home.actors.member, newIssue("Labelled", { labelIds: ["nope" as LabelId] })),
    ).rejects.toBeInstanceOf(NotFoundError);

    await issueService.updateIssue(home.actors.member, {
      orgId: home.org.id,
      issueId: homeIssue.id,
      labelIds: [own.id],
    });
    await expect(
      issueService.updateIssue(home.actors.member, {
        orgId: home.org.id,
        issueId: homeIssue.id,
        title: "Changed title",
        labelIds: [foreign.id],
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    const unchanged = await issueRepo.findIssueById(home.org.id, homeIssue.id);
    expect(unchanged?.title).toBe("Home issue");
    expect(unchanged?.labelIds).toEqual([own.id]);

    // A stale attachment written before labels were checked is never shown.
    await labelRepo.setIssueLabels(home.org.id, homeIssue.id, [own.id, foreign.id]);
    const read = await issueService.getIssue(home.actors.member, home.org.id, homeIssue.id);
    expect(read.labels.map((label) => label.id)).toEqual([own.id]);
    expect(read.issue.labelIds).toEqual([own.id]);
    const page = await issueRepo.listIssuesWithRelations({
      orgId: home.org.id,
      limit: 25,
      cursor: null,
    });
    const listed = page.items.find((item) => item.issue.id === homeIssue.id);
    expect(listed?.labels.map((label) => label.id)).toEqual([own.id]);
    const byForeign = await issueRepo.listIssues({
      orgId: home.org.id,
      labelIds: [foreign.id],
      limit: 25,
      cursor: null,
    });
    expect(byForeign.items).toEqual([]);
  });
});

describe("assignees and project leads", () => {
  it("only accepts current members of the workspace", async () => {
    const stranger = other.userIds.member;

    await expect(
      issueService.createIssue(home.actors.member, newIssue("Stranger", { assigneeId: stranger })),
    ).rejects.toBeInstanceOf(NotFoundError);

    const assigned: unknown[] = [];
    const off = subscribe("issue.assigned", (payload) => {
      assigned.push(payload);
    });
    try {
      await expect(
        issueService.assignIssue(home.actors.member, {
          orgId: home.org.id,
          issueId: homeIssue.id,
          assigneeId: stranger,
        }),
      ).rejects.toBeInstanceOf(NotFoundError);
      expect(assigned).toEqual([]);
      expect((await issueRepo.findIssueById(home.org.id, homeIssue.id))?.assigneeId).toBeNull();

      const departed = await memberRepo.findMember(home.org.id, home.userIds.viewer);
      await memberRepo.archiveMember(home.org.id, departed!.id);
      await expect(
        issueService.assignIssue(home.actors.member, {
          orgId: home.org.id,
          issueId: homeIssue.id,
          assigneeId: home.userIds.viewer,
        }),
      ).rejects.toBeInstanceOf(NotFoundError);
      expect(assigned).toEqual([]);

      await issueService.assignIssue(home.actors.member, {
        orgId: home.org.id,
        issueId: homeIssue.id,
        assigneeId: home.userIds.admin,
      });
      expect(assigned).toHaveLength(1);
    } finally {
      off();
    }
  });

  it("applies the same rule to project leads", async () => {
    const projectsBefore = await projectRepo.countProjects(home.org.id);
    await expect(
      projectService.createProject(home.actors.admin, {
        orgId: home.org.id,
        name: "Stranger led",
        slug: "stranger-led",
        key: "STR",
        description: null,
        visibility: "org",
        leadId: other.userIds.owner,
        color: "#6366f1",
        targetDate: null,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await projectRepo.countProjects(home.org.id)).toBe(projectsBefore);

    await expect(
      projectService.updateProject(home.actors.admin, {
        orgId: home.org.id,
        projectId: home.project.id,
        name: "Renamed",
        leadId: other.userIds.owner,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    const project = await projectRepo.findProjectById(home.org.id, home.project.id);
    expect(project?.name).not.toBe("Renamed");
    expect(project?.leadId).toBe(home.userIds.owner);

    await expect(
      projectService.updateProject(home.actors.admin, {
        orgId: home.org.id,
        projectId: home.project.id,
        leadId: home.userIds.admin,
      }),
    ).resolves.toMatchObject({ leadId: home.userIds.admin });
  });
});

describe("parent issues", () => {
  it("must be a live issue of the same project", async () => {
    const sibling = await projectRepo.insertProject({
      orgId: home.org.id,
      name: "Sibling",
      slug: "sibling",
      key: "SIB",
      description: null,
      visibility: "org",
      leadId: home.userIds.owner,
      color: "#6366f1",
      targetDate: null,
    });
    const siblingIssue = await issueService.createIssue(
      home.actors.member,
      issueInput(home.org.id, sibling.id, { title: "In another project" }),
    );
    const archived = await issueService.createIssue(home.actors.member, newIssue("Soon archived"));
    await issueService.archiveIssue(home.actors.member, home.org.id, archived.id);

    const before = await countIssues();
    await expect(
      issueService.createIssue(home.actors.member, newIssue("Child", { parentId: otherIssue.id })),
    ).rejects.toBeInstanceOf(TenantScopeError);
    for (const parentId of [siblingIssue.id, archived.id, "missing" as Issue["id"]]) {
      await expect(
        issueService.createIssue(home.actors.member, newIssue("Child", { parentId })),
      ).rejects.toBeInstanceOf(NotFoundError);
    }
    expect(await countIssues()).toBe(before);

    const child = await issueService.createIssue(
      home.actors.member,
      newIssue("Child", { parentId: homeIssue.id }),
    );
    expect(child.parentId).toBe(homeIssue.id);
  });
});

describe("replies and mentions", () => {
  const reply = (issueId: Issue["id"], parentId: Comment["id"] | null, extra: Record<string, unknown> = {}) => ({
    orgId: home.org.id,
    issueId,
    body: "a reply",
    parentId,
    mentionedUserIds: [],
    ...extra,
  });

  it("only replies to a live, top-level comment on the same issue", async () => {
    const top = await commentService.createComment(home.actors.member, reply(homeIssue.id, null));
    const nested = await commentService.createComment(home.actors.member, reply(homeIssue.id, top.id));
    const deleted = await commentService.createComment(home.actors.member, reply(homeIssue.id, null));
    await commentService.deleteComment(home.actors.member, { orgId: home.org.id, commentId: deleted.id });

    const secondIssue = await issueService.createIssue(home.actors.member, newIssue("Second issue"));
    const elsewhere = await commentService.createComment(home.actors.member, reply(secondIssue.id, null));
    const foreign = await commentService.createComment(other.actors.member, {
      orgId: other.org.id,
      issueId: otherIssue.id,
